  {
    int color_size = active_cards_count[player];
    int tapped_for_color[color_size][5];
    memset(tapped_for_color, 0, sizeof tapped_for_color);
    int attempts_left = 50;
    int scan_size = color_size;
    for (;;)
    {
      int clrs[6] = {cless, black, blue, green, red, white};
      int tc = 0;
      if (scan_size > 0)
      {
        int i = 0;
        do
        {
          if (in_play(player, i) && !is_tapped(player, i) && is_what(player, i, TYPE_CREATURE))
          {
            unsigned int color = get_color(player, i);
            for (int k = 1; k != 6; ++k)
            {
              if ((color >> k & 1U) && clrs[k] > 0 && tapped_for_color[i][k - 1] != 1)
              {
                --clrs[k];
                tapped_for_color[i][k - 1] = 1;
                add_state(player, i, STATE_TAPPED);
                tapped[tc++] = i;
                goto after_creature;
              }
            }
            if (clrs[0] != 0)
            {
              add_state(player, i, STATE_TAPPED);
              tapped[tc++] = i;
              --clrs[0];
            }
          }
        after_creature:
          if (clrs[0] + clrs[1] + clrs[2] + clrs[3] + clrs[4] + clrs[5] == 0)
          {
            if (spell_fizzled != 1)
            {
              for (int j = 0; j < tc; ++j)
                tap_card(player, tapped[j]);
              return (unsigned int)(spell_fizzled != 1);
            }
            break;
          }
          ++i;
        } while (i < active_cards_count[player]);
        for (int j = 0; j < tc; ++j)
          remove_state(player, tapped[j], STATE_TAPPED);
      }
      --attempts_left;
      if (attempts_left == 0)
      {
        spell_fizzled = 1;
        return (unsigned int)(spell_fizzled != 1);
      }
      scan_size = active_cards_count[player];
    }
  }
  int clrs[6] = {cless, black, blue, green, red, white};
  int tc = 0;
  do
  {
    if (!can_target(&td))
      break;
    if (!select_target(0, card, &td, "Select a creature to tap for Convoke.", NULL))
    {
      spell_fizzled = 1;
      goto rollback;
    }
    instance->number_of_targets = 0;
    if (will_tap_permanent_for_convoke(instance->targets[0].player, instance->targets[0].card,
                                            clrs))
    {
      add_state(instance->targets[0].player, instance->targets[0].card, STATE_TAPPED);
      tapped[tc++] = instance->targets[0].card;
    }
  } while (clrs[1] + clrs[0] + clrs[2] + clrs[3] + clrs[4] + clrs[5] != 0);
  if (spell_fizzled == 1)
  {
  rollback:
    for (int i = 0; i < tc; ++i)
      remove_state(0, tapped[i], STATE_TAPPED);
  }
  else
  {
    for (int i = 0; i < tc; ++i)
      tap_card(0, tapped[i]);
  }
  return (unsigned int)(spell_fizzled != 1);
}

static void pick_human_card(int *picks, int *pack, EXPANSION_t expansion)
{
  int selected;
  for (;;)
  {
    if (picks[0] >= 0)
    {
      selected = show_deck_force_expansion(HUMAN, pack, 500, "Draft a card", 0,
                                                "View prev", expansion);
      if (selected >= 0)
        break;
      show_deck(HUMAN, picks, 500, "Drafted so far", 0,
                     (int)(uintptr_t)EXE_STR(0x78f0a8));
    }
    else
    {
      selected = show_deck_force_expansion(HUMAN, pack, 500, "Draft a card", 1, "",
                                                expansion);
      if (selected >= 0)
        break;
    }
  }
  pick_card(picks, pack, selected);
}

static void pick_ai_card(int *picks, int *pack, color_test_t *drafted_colors, int oppnum)
{
  (void)oppnum;
  int num_drafted_colors = num_bits_set(*drafted_colors);
  int max_score = -1, best_card = -1, max_score_backup = -1, best_card_backup = 0;
  for (int i = 0; pack[i] >= 0; ++i)
  {
    int iid = pack[i];
    card_data_t *cd = &cards_data[iid];
    int score = cards_ptr[cd->id]->ai_base_value + internal_rand(10);
    if (score > max_score_backup)
    {
      max_score_backup = score;
      best_card_backup = i;
    }
    if (score <= max_score)
      continue;
    color_test_t color = cd->color & COLOR_TEST_ANY_COLORED;
    int num_card_colors = num_bits_set(color);
    if (num_card_colors > 1 && num_drafted_colors < 2)
      continue;
    int candidate = i, reject = 0, restrict_color = 1;
    if (cd->type & (TYPE_LAND | TYPE_ARTIFACT))
      if (num_card_colors == 0 || num_card_colors == 5 || !(color & ~(*drafted_colors)))
        restrict_color = DRAFT_IS_BASIC(cd->id);
    if (restrict_color)
    {
      if (num_drafted_colors >= 2)
        reject = (color & ~(*drafted_colors)) != 0;
      else if (num_drafted_colors == 1)
        reject = num_bits_set(color | *drafted_colors) > 2;
    }
    if (reject)
    {
      candidate = best_card;
      if (i != best_card)
        continue;
    }
    best_card = candidate;
    max_score = score;
  }
  if (best_card == -1)
    best_card = best_card_backup;
  card_data_t *cd = &cards_data[pack[best_card]];
  color_test_t color = cd->color & COLOR_TEST_ANY_COLORED;
  if (num_bits_set(color | *drafted_colors) < 3 && !DRAFT_IS_BASIC(cd->id))
    *drafted_colors |= color;
  pick_card(picks, pack, best_card);
}

static void make_ai_deck(int *iids, int iids_size, color_test_t drafted_colors, int oppnum)
{
  (void)oppnum;
  int num_in_iids;
  {
    target_t deck[iids_size];
    memset(deck, 255, sizeof(deck));
    int num_in_deck = 0;
    for (int i = 0; iids[i] >= 0; ++i)
    {
      card_data_t *cd = &cards_data[iids[i]];
      int score = cards_ptr[cd->id]->ai_base_value;
      if (DRAFT_IS_BASIC(cd->id))
        score -= 100;
      color_test_t color = cd->color & COLOR_TEST_ANY_COLORED;
      if ((cd->type & (TYPE_LAND | TYPE_ARTIFACT)) && (cd->extra_ability & EA_MANA_SOURCE))
      {
        int matching_colors = num_bits_set(cd->color & drafted_colors);
        score += (matching_colors * 3 + 2) * (matching_colors * 3 + 2);
      }
      else if (!(cd->type & TYPE_LAND) || (cd->type & TYPE_ARTIFACT))
      {
        if (color & ~drafted_colors)
          score -= 50;
        else if ((color & drafted_colors) == drafted_colors)
          score += 10;
      }
      deck[num_in_deck].player = score;
      deck[num_in_deck++].card = iids[i];
    }
    descending_qsort_on_player(num_in_deck, deck);
    memset(iids, 255, iids_size * sizeof(int));
    num_in_iids = 0;
    int num_nonland_in_iids = 0;
    for (int i = 0; i < num_in_deck && num_nonland_in_iids < 23; ++i)
    {
      if (num_in_iids >= iids_size - 1)
        backtrace_and_abort("functions/draft.c:207\nnum_in_iids < iids_size - 1");
      iids[num_in_iids++] = deck[i].card;
      num_nonland_in_iids += (cards_data[deck[i].card].type & TYPE_LAND) == 0;
    }
  }
  {
    int basics[5], num_basics = 0;
    if (drafted_colors & COLOR_TEST_BLACK)
      basics[num_basics++] = get_internal_card_id_from_csv_id(CARD_ID_SWAMP);
    if (drafted_colors & COLOR_TEST_BLUE)
      basics[num_basics++] = get_internal_card_id_from_csv_id(CARD_ID_ISLAND);
    if (drafted_colors & COLOR_TEST_RED)
      basics[num_basics++] = get_internal_card_id_from_csv_id(CARD_ID_MOUNTAIN);
    if (drafted_colors & COLOR_TEST_GREEN)
      basics[num_basics++] = get_internal_card_id_from_csv_id(CARD_ID_FOREST);
    if ((drafted_colors & COLOR_TEST_WHITE) || !num_basics)
      basics[num_basics++] = get_internal_card_id_from_csv_id(CARD_ID_PLAINS);
    int basicidx = 0;
    while (num_in_iids < 40)
    {
      iids[num_in_iids++] = basics[basicidx];
      basicidx = (basicidx + 1) % num_basics;
    }
  }
  if (num_in_iids >= iids_size - 1)
    backtrace_and_abort("functions/draft.c:233\nnum_in_iids < iids_size - 1");
  iids[num_in_iids] = -1;
}

static int ai_blockers_guts(void)
{
  int *assignment = EXE_DWORD_PTR(0x607ae4);
  int *attack_cards = EXE_DWORD_PTR(0x607698);
  int *num_blocks = EXE_DWORD_PTR(0x607d78);
  int *blocker_cards = EXE_DWORD_PTR(0x608304);
  ai_defensive_modifier = 0;
  int life_if_unblocked = life[ai_combat_defending_player];
  int cop_times = EXE_DWORD(0x60a42c);
  int outflanked[EXE_DWORD(0x607d54) + 1];
  memset(outflanked, 0, (EXE_DWORD(0x607d54) + 1) * sizeof(int));
  int cop_benefit[16], blockers_that_will_be_destroyed[16];
  int num_cop_benefit = 0, rating = 0, rampage = 0;
  for (int a = 0; a < EXE_DWORD(0x607ccc); ++a)
  {
    int attack_power = EXE_DWORD_PTR(0x6081fc)[a];
    int attack_toughness = EXE_DWORD_PTR(0x6077a0)[a];
    int attacker = attack_cards[a];
    ai_defensive_modifier += EXE_DWORD_PTR(0x607cd0)[a];
    int attacker_flanking =
        check_for_special_ability(1 - ai_combat_defending_player, attacker, 0x2000);
    int num_destroyed = 0, any_blockers_have_banding = 0, any_destroyed = 0;
    int total_pow = 0, total_tgh = 0, num_blocking = 0;
    uint32_t attacker_bit = 1u << (a & 31);
    for (int b = 0; b < EXE_DWORD(0x607d54); ++b)
    {
      if (assignment[b] != attacker)
        continue;
      ++num_blocking;
      if (num_blocking == 2 &&
          check_for_special_ability(1 - ai_combat_defending_player, attacker, 0x40))
        rampage = dispatch_event_with_attacker(1 - ai_combat_defending_player, attacker,
                                               (event_t)0x5e00, -1, 0x40);
      ai_defensive_modifier += EXE_DWORD_PTR(0x607c70)[b];
      int original_tgh = EXE_DWORD_PTR(0x6077e0)[b];
      int tgh = original_tgh, flanked = 0;
      if (attacker_flanking && !check_for_special_ability(ai_combat_defending_player,
                                                               blocker_cards[b], 0x2000))
      {
        if (original_tgh < 2)
        {
          outflanked[b] = 1;
          any_destroyed = 1;
          blockers_that_will_be_destroyed[num_destroyed++] = b;
          continue;
        }
        --tgh;
        flanked = 1;
      }
      outflanked[b] = 0;
      int pow = EXE_DWORD_PTR(0x6082c0)[b] - flanked;
      total_pow += pow > 0 ? pow : 0;
      total_tgh += tgh > 0 ? tgh : 0;
      if (EXE_DWORD_PTR(0x607618)[b] & 0x40)
        any_blockers_have_banding = 1;
      if ((uint32_t)EXE_DWORD_PTR(0x607d58)[b] & attacker_bit)
        total_pow += 99;
      int destroys_this = ((uint32_t)EXE_DWORD_PTR(0x607cb0)[a] >> (b & 31)) & 1;
      if (destroys_this)
        any_destroyed = destroys_this;
      else if (!any_destroyed && attack_power < original_tgh)
      {
        any_destroyed = 0;
        continue;
      }
      if (!(EXE_DWORD_PTR(0x607618)[b] & 0x200))
        blockers_that_will_be_destroyed[num_destroyed++] = b;
    }
    int32_t combinations = 1u << (num_destroyed & 31);
    if (rampage > 0)
    {
      rampage *= num_blocking - 1;
      attack_power += rampage;
      attack_toughness += rampage;
    }
    uint32_t attack_abils = EXE_DWORD_PTR(0x6075d8)[a];
    int new_life = life_if_unblocked, evaluate_damage = 0;
    if (num_blocking < minimum_blockers(1 - ai_combat_defending_player, attacker))
    {
      if (!EXE_DWORD(0x60a424) || EXE_DWORD(0x60a424) <= EXE_DWORD_PTR(0x607820)[a])
      {
        if (player_bits[1 - ai_combat_defending_player] & 0x80000)
        {
          int commander_damage =
              check_special_flags2(1 - ai_combat_defending_player, attacker, 0x1000000);
          if (!commander_damage)
          {
            int commander = get_commander_id(1 - ai_combat_defending_player, 1);
            if (commander == get_id(1 - ai_combat_defending_player, attacker))
              commander_damage = 1;
            else
            {
              commander = get_commander_id(1 - ai_combat_defending_player, 2);
              if (commander == get_id(1 - ai_combat_defending_player, attacker))
                commander_damage = 1;
            }
          }
          if (commander_damage)
          {
            int edh = locate_edh_card(1 - ai_combat_defending_player);
            if (count_counters(1 - ai_combat_defending_player, edh, (counter_t)0x1c) +
                    attack_power >=
                21)
              new_life -= 9999;
          }
        }
        new_life -= mod_pow_unblocked(attack_power, 1 - ai_combat_defending_player, attacker);
        evaluate_damage = 1;
      }
    }
    else if ((attack_abils & 0x80) && total_tgh < attack_power)
    {
      new_life -= attack_power - total_tgh;
      evaluate_damage = 1;
    }
    if (evaluate_damage)
    {
      if (EXE_DWORD(0x60a428) && new_life < life_if_unblocked &&
          (EXE_DWORD(0x60a428) & get_color(1 - ai_combat_defending_player, attacker)))
        cop_benefit[num_cop_benefit++] = life_if_unblocked - new_life;
      life_if_unblocked = new_life;
    }
    if (num_blocking > 0 &&
        ((attack_toughness <= total_pow && (!(attack_abils & 0x300) || num_destroyed < 1)) ||
         (EXE_DWORD(0x60a424) && EXE_DWORD_PTR(0x607820)[a] < EXE_DWORD(0x60a424))))
    {
      int64_t convert_64 = (int64_t)EXE_DWORD_PTR(0x60823c)[a] *
                           EXE_DWORD_PTR(0x628c14)[3 - ai_combat_defending_player];
      rating += (int)(convert_64 / 8);
    }
    int best_opinion = -1;
    int effective_attack_power = any_destroyed ? 99 : attack_power;
    total_pow -= num_blocking;
    for (int32_t combo = 0; combo < combinations; ++combo)
    {
      int remaining = effective_attack_power, attack_rating = 0;
      if (!any_destroyed && any_blockers_have_banding)
      {
        if (total_pow < effective_attack_power)
        {
          attack_rating = combo ? 9999 : 0;
          for (int k = 0; k < num_destroyed; ++k)
          {
            if (!(combo & (1u << (k & 31))))
              continue;
            int n = blockers_that_will_be_destroyed[k];
            if (EXE_DWORD_PTR(0x6077e0)[n] <= effective_attack_power)
            {
              int value = EXE_DWORD_PTR(0x60834c)[n];
              remaining = is_protected_from(ai_combat_defending_player, blocker_cards[n],
                                                 1 - ai_combat_defending_player, attacker,
                                                 IPF_DAMAGE);
              if (!remaining)
              {
                if (value < attack_rating)
                  attack_rating = value;
                break;
              }
            }
            attack_rating = 0;
            remaining = effective_attack_power;
          }
        }
      }
      else
      {
        for (int l = 0; l < num_destroyed; ++l)
        {
          if (!(combo & (1u << (l & 31))))
            continue;
          int n = blockers_that_will_be_destroyed[l];
          if (!(EXE_DWORD_PTR(0x607618)[n] & 0x100) ||
              EXE_DWORD_PTR(0x6082c0)[n] < attack_toughness)
          {
            if (outflanked[n] || !is_protected_from(
                                     ai_combat_defending_player, blocker_cards[n],
                                     1 - ai_combat_defending_player, attacker, IPF_DAMAGE))
              attack_rating += EXE_DWORD_PTR(0x60834c)[n];
          }
          remaining -= EXE_DWORD_PTR(0x6077e0)[n];
          if (remaining < 0)
            break;
        }
      }
      if (remaining >= 0 && best_opinion < attack_rating)
        best_opinion = attack_rating;
    }
    rating -= best_opinion;
  }
  rating += ai_defensive_modifier;
  while (cop_times != 0 && num_cop_benefit > 0)
  {
    int best = 0, best_idx = 0;
    for (int i = 0; i < num_cop_benefit; ++i)
    {
      if (best < cop_benefit[i])
      {
        best = cop_benefit[i];
        best_idx = i;
      }
    }
    if (!best)
      break;
    --cop_times;
    life_if_unblocked += cop_benefit[best_idx];
    cop_benefit[best_idx] = 0;
  }
  int penalty;
  if (life_if_unblocked < 1)
    penalty = life_if_unblocked * -96 + 999;
  else
  {
    int64_t rating_64 = (int64_t)(life[ai_combat_defending_player] - life_if_unblocked) *
                        EXE_DWORD_PTR(0x628c14)[ai_combat_defending_player];
    penalty = (int)((rating_64 * 6) / life_if_unblocked);
  }
  return rating - penalty;
}

static void check_pow_tgh_boost(iid_t iid, int player, int card, int *pow_loc, int *tgh_loc)
{
  uint32_t ea = cards_data[iid].extra_ability;
  CardFunction fn = cards_data[iid].code_pointer;
  card_instance_t *inst = get_card_instance(player, card);
  int base_power = *pow_loc, base_toughness = *tgh_loc;
  if (ea & 0x18)
  {
    int8_t old_activating_player = EXE_DWORD(0x7a3610);
    EXE_DWORD(0x7a3610) = player;
    int swapped = check_special_flags3(player, card, 0x100000);
    if (!swapped)
    {
      if (ea & 8)
        *pow_loc = base_power + call_card_fn(fn, inst, player, card, EVENT_POW_BOOST);
      if (ea & 0x10)
        *tgh_loc = base_toughness + call_card_fn(fn, inst, player, card, EVENT_TOU_BOOST);
    }
    else
    {
      if (ea & 8)
        *tgh_loc = base_toughness + call_card_fn(fn, inst, player, card, EVENT_POW_BOOST);
      if (ea & 0x10)
        *pow_loc = base_power + call_card_fn(fn, inst, player, card, EVENT_TOU_BOOST);
    }
    EXE_DWORD(0x7a3610) = old_activating_player;
  }
}

